class Solution {
    public int numberOfWeakCharacters(int[][] properties){
        Arrays.sort(properties,(a,b)->a[0]!=b[0]?b[0]-a[0]:a[1]-b[1]);
        int answer=0,maximum=0;
        for(int[] property:properties){
            if(property[1]<maximum)answer++;
            maximum=Math.max(maximum,property[1]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numberOfWeakCharacters(properties:Array<IntArray>):Int{
        properties.sortWith(compareByDescending<IntArray>{
            it[0]
        }.thenBy{
            it[1]
        });
        var answer=0;
        var maximum=0;
        for(property in properties){
            if(property[1]<maximum)answer++;
            maximum=maxOf(maximum,property[1])
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int numberOfWeakCharacters(vector<vector<int>>& properties){
        sort(properties.begin(),properties.end(),[](auto& a,auto& b){
            return a[0]!=b[0]?a[0]>b[0]:a[1]<b[1];
        });
        int answer=0,maximum=0;
        for(auto& property:properties){
            answer+=property[1]<maximum;
            maximum=max(maximum,property[1]);
        }
        return answer;
    }
};
